"""Check actual saved generated bytes; do not invoke any audio decoder."""
from pathlib import Path
import hashlib
import importlib.util
import json

PREP = Path(__file__).resolve().parent
OUT = PREP / "generated01"


def fact(path, relative=None):
    raw = path.read_bytes()
    return dict(path=path.relative_to(relative).as_posix() if relative else str(path),
                bytes=len(raw), sha256=hashlib.sha256(raw).hexdigest())


def main():
    spec = importlib.util.spec_from_file_location("reviewed_generator", PREP / "generate.py")
    g = importlib.util.module_from_spec(spec); spec.loader.exec_module(g)
    manifest = json.loads((OUT / "manifest.json").read_bytes())
    matrix = json.loads((OUT / "matrix.json").read_bytes())
    checks = json.loads((OUT / "pure-checks.json").read_bytes())
    command = json.loads((PREP / "construction01.command.json").read_bytes())
    assert command["returncode"] == 0 and command["source_before"] == command["source_after"]
    assert checks["inputs_before"] == checks["inputs_after"]
    for row in manifest["files"]:
        assert fact(OUT / row["path"], OUT) == row, row["path"]
    for row in checks["inputs_after"]:
        assert fact(Path(row["path"])) == row, row["path"]
    assert len(manifest["files"]) == 108 and len(matrix["cases"]) == 21
    assert [(c["rate"], c["channels"]) for c in matrix["cases"][:18]] == [(r, c) for r in g.RATES for c in (1, 2)]
    rows, total = [], 0
    for index, case in enumerate(matrix["cases"]):
        raw = {kind: (OUT / case[kind]).read_bytes() for kind in ("identification", "setup", "comment", "audio")}
        assert {k: hashlib.sha256(v).hexdigest() for k, v in raw.items()} == case["raw_sha256"]
        info = raw["identification"]
        assert len(info) == 30 and info[:7] == b"\x01vorbis" and raw["setup"][:7] == b"\x05vorbis"
        assert (info[11], int.from_bytes(info[12:16], "little"), 1 << (info[28] & 15), 1 << (info[28] >> 4)) == (
            case["channels"], case["rate"], case["short"], case["long"])
        variant = case["id"].split("-c")[0]
        g.inspect_setup(raw["setup"], variant, case["channels"])
        offsets = case["offsets"]
        assert len(offsets) == 15 and offsets[0] == 0 and offsets[-1] == len(raw["audio"])
        assert all(a < b for a, b in zip(offsets, offsets[1:]))
        packets = [raw["audio"][a:b] for a, b in zip(offsets, offsets[1:])]
        for packet, data in enumerate(packets): g.inspect_packet(data, packet, variant, case["channels"])
        modes = case["mode_flags"]; assert modes == list(g.MODES)
        frames = [0] + [((case["long"] if a else case["short"]) + (case["long"] if b else case["short"])) // 4
                        for a, b in zip(modes, modes[1:])]
        pcm = [f * case["channels"] * 2 for f in frames]
        assert frames == case["expected_packet_frames"] == case["expected_packet_samples"]
        assert pcm == case["expected_packet_s16le_bytes"] and sum(pcm) == case["expected_s16le_bytes"]
        assert sum(frames) == case["expected_raw_samples"]
        carrier = (OUT / case["ogg"]).read_bytes()
        assert hashlib.sha256(carrier).hexdigest() == case["ogg_sha256"]
        pages = g.base.read_pages(carrier)
        assert [p["packet"] for p in pages] == [info, raw["comment"], raw["setup"]] + packets
        assert [p["granule"] for p in pages] == [0, 0, 0] + case["packet_granules"]
        assert [p["flags"] for p in pages] == [2] + [0] * 15 + [4]
        total += sum(pcm)
        rows.append(dict(index=index, id=case["id"], rate=case["rate"], channels=case["channels"],
            raw_packet_count=len(packets), expected_pcm_bytes=sum(pcm), raw_payload_bytes={k: len(v) for k, v in raw.items()}))
    assert total == matrix["expected_total_s16le_bytes"] == 464640
    assert len(checks["exact_rejection_controls"]) == 6 and all(c["rejected"] for c in checks["exact_rejection_controls"])
    assert [fact(Path(row["path"])) for row in checks["inputs_after"]] == checks["inputs_after"]
    result = dict(schema="vorbis-mono-mapping-saved-payload-readback-v1", completed=True,
        scope="source construction only; no decoder or PCM synthesis", stored_files_checked=108,
        full_raw_files_checked=84, carriers_checked=21, raw_packets_checked=294, expected_pcm_bytes=total,
        input_identities_unchanged=4, exact_negative_controls=checks["exact_rejection_controls"], cases=rows,
        matrix=fact(OUT / "matrix.json"), manifest=fact(OUT / "manifest.json"), command=fact(PREP / "construction01.command.json"),
        original_readback_nonpass=fact(PREP / "readback01.failure.json"),
        independent_PCM_nonzero_observed=False, target_qualification=False)
    with (PREP / "readback02.json").open("x", encoding="utf-8", newline="\n") as stream:
        json.dump(result, stream, indent=2); stream.write("\n")
    print(json.dumps(dict(readback=fact(PREP / "readback02.json"), cases=21, packets=294, source_only=True)))


if __name__ == "__main__":
    main()
